function r6DashboardDataProduction(array $base):array{
    $pdo=db();$u=currentUser(loadStore());$scope=($u['role']??'')==='entity_admin'?(int)($u['company_id']??0):0;$filter=$scope?' WHERE company_id='.(int)$scope:'';$base['onboarding_import_jobs']=$pdo->query("SELECT * FROM onboarding_import_jobs".$filter." ORDER BY created_at DESC,id DESC LIMIT 100")->fetchAll();$base['onboarding_import_errors']=[];$base['ap_payment_batches']=$pdo->query("SELECT * FROM ap_payment_batches".$filter." ORDER BY scheduled_date DESC,id DESC LIMIT 200")->fetchAll();$base['ap_payment_batch_lines']=$pdo->query("SELECT bl.* FROM ap_payment_batch_lines bl JOIN ap_payment_batches b ON b.id=bl.batch_id".($scope?' WHERE b.company_id='.(int)$scope:'')." ORDER BY bl.id DESC LIMIT 500")->fetchAll();$base['document_attachments']=$pdo->query("SELECT id,company_id,entity_type,entity_id,original_name,mime_type,file_size,sha256,description,created_at FROM document_attachments".$filter.($filter?' AND':' WHERE')." is_active=1 ORDER BY created_at DESC,id DESC LIMIT 200")->fetchAll();$from=date('Y-m-d');$to=date('Y-m-d',strtotime('+90 days'));$batchForecast=r6PaymentBatchForecastRows($base['ap_payment_batches'],$from,$to);$base['cash_forecast_items']=array_merge($base['cash_forecast_items']??[],$batchForecast);$base['cash_forecast_summary']=(new \Nexa\Treasury\CashForecastService())->summarize($base['cash_forecast_items'],$from,$to);return$base;
}
function r6Audit(string $action,array $payload=[]):void{writeAudit($action,$payload);}
